CREATE TABLE "EnergyPolicy" ("id" TEXT NOT NULL PRIMARY KEY DEFAULT 'GLOBAL', "minimumMainsVoltage" REAL NOT NULL DEFAULT 180, "maximumMainsVoltage" REAL NOT NULL DEFAULT 260, "inverterReservePct" REAL NOT NULL DEFAULT 25, "inverterMaxWatts" REAL NOT NULL DEFAULT 3000, "generatorMaxWatts" REAL NOT NULL DEFAULT 5000, "restoreStableSeconds" INTEGER NOT NULL DEFAULT 120, "mainsContactorNodeId" TEXT, "automaticProtection" BOOLEAN NOT NULL DEFAULT true, "updatedAt" DATETIME NOT NULL);
CREATE TABLE "EnergyLoad" ("id" TEXT NOT NULL PRIMARY KEY, "deviceId" TEXT NOT NULL, "hardwareNodeId" TEXT, "name" TEXT NOT NULL, "priority" INTEGER NOT NULL DEFAULT 3, "ratedWatts" REAL NOT NULL, "sheddable" BOOLEAN NOT NULL DEFAULT true, "compressorLoad" BOOLEAN NOT NULL DEFAULT false, "minimumOffSeconds" INTEGER NOT NULL DEFAULT 180, "restoreMode" TEXT NOT NULL DEFAULT 'MANUAL', "enabled" BOOLEAN NOT NULL DEFAULT true, "updatedAt" DATETIME NOT NULL);
CREATE TABLE "PowerSnapshot" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "source" TEXT NOT NULL, "voltage" REAL NOT NULL, "totalWatts" REAL NOT NULL, "batteryPct" REAL, "solarWatts" REAL, "timestamp" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "AutomationRule" ("id" TEXT NOT NULL PRIMARY KEY, "name" TEXT NOT NULL, "enabled" BOOLEAN NOT NULL DEFAULT true, "triggerType" TEXT NOT NULL, "triggerConfig" TEXT NOT NULL, "conditions" TEXT NOT NULL DEFAULT '[]', "actions" TEXT NOT NULL, "mode" TEXT NOT NULL DEFAULT 'SINGLE', "maxRuns" INTEGER NOT NULL DEFAULT 1, "cooldownSeconds" INTEGER NOT NULL DEFAULT 0, "lastRunAt" DATETIME, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL);
CREATE TABLE "AutomationRun" ("id" TEXT NOT NULL PRIMARY KEY, "ruleId" TEXT NOT NULL, "eventType" TEXT NOT NULL, "eventPayload" TEXT NOT NULL, "status" TEXT NOT NULL, "result" TEXT, "startedAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "completedAt" DATETIME);
CREATE TABLE "Notification" ("id" TEXT NOT NULL PRIMARY KEY, "type" TEXT NOT NULL, "priority" TEXT NOT NULL DEFAULT 'NORMAL', "title" TEXT NOT NULL, "message" TEXT NOT NULL, "data" TEXT, "status" TEXT NOT NULL DEFAULT 'UNREAD', "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "readAt" DATETIME);
CREATE TABLE "GeofencePlace" ("id" TEXT NOT NULL PRIMARY KEY, "name" TEXT NOT NULL, "category" TEXT NOT NULL, "latitude" REAL NOT NULL, "longitude" REAL NOT NULL, "radiusMetres" REAL NOT NULL DEFAULT 250, "enabled" BOOLEAN NOT NULL DEFAULT true, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "EnergyLoad_deviceId_key" ON "EnergyLoad"("deviceId");
CREATE INDEX "PowerSnapshot_timestamp_idx" ON "PowerSnapshot"("timestamp");
CREATE INDEX "AutomationRun_ruleId_startedAt_idx" ON "AutomationRun"("ruleId", "startedAt");
CREATE INDEX "Notification_status_createdAt_idx" ON "Notification"("status", "createdAt");
